package com.kgsat.order.producer;
import com.kgsat.order.model.OrderEvent; import org.slf4j.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.stereotype.Component;
@Component public class OrderProducer { private static final Logger log=LoggerFactory.getLogger(OrderProducer.class); private final KafkaTemplate<String,OrderEvent> kafka; private final String topic; public OrderProducer(KafkaTemplate<String,OrderEvent> kafka,@Value("${app.kafka.orders-topic}") String topic){this.kafka=kafka;this.topic=topic;} public void send(OrderEvent event){kafka.send(topic,event.orderId(),event).whenComplete((r,e)->{if(e!=null) log.error("event=kafka_produce_failed orderId={}",event.orderId(),e); else log.info("event=kafka_produced topic={} orderId={} partition={}",topic,event.orderId(),r.getRecordMetadata().partition());});} }
